export function movieAvailable(film,now=Date.now()){return film.available===true&&Number.isFinite(Date.parse(film.rightsStart))&&now>=Date.parse(film.rightsStart)&&(!film.rightsEnd||now<Date.parse(film.rightsEnd))&&typeof film.url==='string'&&(/^(assets\/movies\/|https:\/\/)/.test(film.url));}

export function validMovieWatch(w){return w===undefined||!!w&&typeof w==='object'&&!Array.isArray(w)&&Object.keys(w).length<=200&&Object.entries(w).every(([id,v])=>/^[a-z0-9-]{1,64}$/.test(id)&&v&&Number.isFinite(v.position)&&v.position>=0&&v.position<=10000000&&typeof v.completed==='boolean');}
